using Jose;

var doc = JsonDocument.Parse(File.ReadAllText("jwe.json"));
var root = doc.RootElement;

string compact =
    root.GetProperty("protected").GetString + "." +
    root.GetProperty("encrypted_key").GetString + "." +
    root.GetProperty("iv").GetString + "." +
    root.GetProperty("ciphertext").GetString + "." +
    root.GetProperty("tag").GetString;

